1	import 'server-only';
2	import type { Allergen, DietFlag, UserProfile } from '@/contracts/domain';
3	import sql from '@/lib/db';
4	import { NotFoundError } from '@/lib/errors';
5	import type { UpdateMeInput } from './validation';
6	
7	// Profile reads/writes for /api/me, onboarding and settings (SPEC F1). requireUser() (dev's
8	// src/lib/current-user.ts) only returns identity, so diets/allergens/goals/onboarding come from
9	// here (team decision 2026-11-08). Every query is scoped by the session's user id.
10	
11	interface UserRow {
12	  id: string;
13	  email: string | null;
14	  display_name: string | null;
15	  avatar_url: string | null;
16	  tz: string;
17	  daily_kcal_goal: number | null;
18	  daily_protein_goal_g: number | string | null;
19	  diets: string[];
20	  allergens: string[];
21	  onboarded_at: Date | null;
22	  past_best_before_grace_days: number;
23	}
24	
25	const COLUMNS = [
26	  'id', 'email', 'display_name', 'avatar_url', 'tz', 'daily_kcal_goal', 'daily_protein_goal_g',
27	  'diets', 'allergens', 'onboarded_at', 'past_best_before_grace_days',
28	];
29	/** Fresh fragment per query (postgres.js fragments are lazy query objects; don't share one). */
30	const columns = () => sql(COLUMNS);
31	
32	export function rowToProfile(r: UserRow): UserProfile {
33	  return {
34	    id: r.id,
35	    email: r.email,
36	    displayName: r.display_name,
37	    avatarUrl: r.avatar_url,
38	    tz: r.tz,
39	    dailyKcalGoal: r.daily_kcal_goal == null ? null : Number(r.daily_kcal_goal),
40	    dailyProteinGoalG: r.daily_protein_goal_g == null ? null : Number(r.daily_protein_goal_g),
41	    diets: r.diets as DietFlag[],
42	    allergens: r.allergens as Allergen[],
43	    onboarded: r.onboarded_at !== null,
44	    pastBestBeforeGraceDays: Number(r.past_best_before_grace_days),
45	  };
46	}
47	
48	export async function getProfile(userId: string): Promise<UserProfile> {
49	  const [row] = await sql<UserRow[]>`SELECT ${columns()} FROM users WHERE id = ${userId}`;
50	  if (!row) throw new NotFoundError('User not found');
51	  return rowToProfile(row);
52	}
53	
54	export async function updateProfile(userId: string, patch: UpdateMeInput): Promise<UserProfile> {
55	  const set: Record<string, unknown> = {};
56	  if (patch.displayName !== undefined) set.display_name = patch.displayName;
57	  if (patch.tz !== undefined) set.tz = patch.tz;
58	  if (patch.dailyKcalGoal !== undefined) set.daily_kcal_goal = patch.dailyKcalGoal;
59	  if (patch.dailyProteinGoalG !== undefined) set.daily_protein_goal_g = patch.dailyProteinGoalG;
60	  if (patch.diets !== undefined) set.diets = patch.diets;
61	  if (patch.allergens !== undefined) set.allergens = patch.allergens;
62	  if (patch.pastBestBeforeGraceDays !== undefined) set.past_best_before_grace_days = patch.pastBestBeforeGraceDays;
63	
64	  const keys = Object.keys(set);
65	  const onboard = patch.completeOnboarding === true;
66	  if (keys.length === 0 && !onboard) return getProfile(userId);
67	
68	  const onboardedAt = onboard ? sql`COALESCE(onboarded_at, now())` : sql`onboarded_at`;
69	  const [row] = keys.length
70	    ? await sql<UserRow[]>`
71	        UPDATE users SET ${sql(set, keys)}, onboarded_at = ${onboardedAt}
72	        WHERE id = ${userId} RETURNING ${columns()}`
73	    : await sql<UserRow[]>`
74	        UPDATE users SET onboarded_at = ${onboardedAt}
75	        WHERE id = ${userId} RETURNING ${columns()}`;
76	  if (!row) throw new NotFoundError('User not found');
77	  return rowToProfile(row);
78	}
79	
80	/** Settings → "Delete my data": removes the users row; every user-owned table cascades. */
81	export async function deleteUserData(userId: string): Promise<void> {
82	  const result = await sql`DELETE FROM users WHERE id = ${userId}`;
83	  if (result.count === 0) throw new NotFoundError('User not found');
84	}
